import React from "react";
import { motion } from "framer-motion";

const Feedback = () => {
  return (
    <motion.div
      className="min-h-[80vh] flex flex-col items-center justify-center text-center p-6"
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
    >
      <h1 className="text-3xl font-bold mb-4 text-blue-400">
        AI Feedback Results
      </h1>
      <p className="text-gray-300 max-w-2xl mb-6">
        Once your video is analyzed, you’ll see AI insights here: communication clarity, confidence level, body language, and overall score.
      </p>

      <div className="bg-blue-950/60 border border-blue-800 p-6 rounded-xl shadow-lg max-w-lg w-full text-left">
        <p className="text-gray-400 italic">
          “Your tone was confident, but pacing could be improved. Eye contact maintained well.”
        </p>
        <p className="mt-3 text-blue-400 font-semibold">Score: 8.5 / 10</p>
      </div>
    </motion.div>
  );
};

export default Feedback;
